using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;

var configuration = new ConfigurationBuilder()
    .AddEnvironmentVariables()
    .Build();

var apiKey = configuration["OPENAI_API_KEY"]
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this app.");

var modelId = configuration["OPENAI_MODEL"] ?? "gpt-4o-mini-2024-07-18";

var services = new ServiceCollection();
services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, apiKey));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();

// Define tools the agent can use
var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearch),
    AIFunctionFactory.Create(SaveNote),
    AIFunctionFactory.Create(GetNotes),
};

// Create the research agent
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. When given a topic, you:
        1. Search the web multiple times to gather diverse information
        2. Save important findings as notes
        3. After researching, retrieve your notes and produce a concise summary

        Always search at least 2-3 times with different queries to get broad coverage,
        then save key findings, and finally summarize everything.
        """,
    name: "ResearchAgent",
    description: "Researches topics using web search and note-taking",
    tools: tools);

// Run the agent
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var session = await agent.CreateSessionAsync();
var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session,
    runOptions);

Console.WriteLine("═══ Research Summary ═══\n");
Console.WriteLine(response.Text);

// --- Tool implementations ---

var notes = new List<string>();

[Description("Searches the web for information on a query. Returns relevant search results.")]
static string WebSearch([Description("The search query")] string query)
{
    // Simulated web search results for demonstration.
    // In production, integrate with a real search API (e.g., Bing Search).
    Console.WriteLine($"  🔍 Searching: \"{query}\"");
    return $"""
        Search results for "{query}":
        1. [Wikipedia] Overview article covering key aspects of {query} including history, 
           current state, and future outlook.
        2. [Research Paper] Recent academic study analyzing trends and developments in {query}, 
           published 2024.
        3. [News] Latest developments: Industry experts predict significant changes in {query} 
           over the next 5 years. Key drivers include technology advancement and policy changes.
        4. [Expert Blog] In-depth analysis of {query} with practical implications and 
           recommendations for stakeholders.
        """;
}

[Description("Saves a research note for later reference.")]
string SaveNote([Description("The note content to save")] string content)
{
    notes.Add(content);
    Console.WriteLine($"  📝 Note saved ({notes.Count} total)");
    return $"Note saved successfully. You now have {notes.Count} note(s).";
}

[Description("Retrieves all saved research notes.")]
string GetNotes()
{
    if (notes.Count == 0)
        return "No notes saved yet.";

    Console.WriteLine($"  📋 Retrieving {notes.Count} note(s)");
    return string.Join("\n---\n", notes.Select((n, i) => $"Note {i + 1}: {n}"));
}

